'use strict';

const fs = require('fs');
const path = require('path');

const root = process.cwd();
const sourcePath = path.join(root, 'subject-manifest.json');
const targetPath = path.join(root, 'subject-manifest.js');
const manifest = JSON.parse(fs.readFileSync(sourcePath, 'utf8'));
const output = [
  "'use strict';",
  '',
  '// Generated by scripts/build-subject-manifest.cjs. Edit subject-manifest.json instead.',
  `window.SUBJECT_MANIFEST = ${JSON.stringify(manifest, null, 2)};`,
  ''
].join('\n');

if (process.argv.includes('--check')) {
  const current = fs.existsSync(targetPath) ? fs.readFileSync(targetPath, 'utf8') : '';
  if (current !== output) {
    console.error('subject-manifest.js is stale. Run: node scripts/build-subject-manifest.cjs');
    process.exit(1);
  }
  console.log('PASS SUBJECT-MANIFEST-JS subject-manifest.js matches subject-manifest.json');
} else {
  fs.writeFileSync(targetPath, output);
  console.log('Generated subject-manifest.js from subject-manifest.json');
}
